$pdo->prepare("INSERT INTO source_versions(source_id,version_number,final_url,title,extracted_text,content_hash) VALUES(?,1,?,'Proactive v1','Original',?)")->execute([$sourceId,$url,hash('sha256','p17-v1')]);$v1=(int)$pdo->lastInsertId();
$pdo->prepare("INSERT INTO source_versions(source_id,version_number,final_url,title,extracted_text,content_hash) VALUES(?,2,?,'Proactive v2','Changed',?)")->execute([$sourceId,$url,hash('sha256','p17-v2')]);$v2=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE sources SET current_version_id=? WHERE id=?')->execute([$v2,$sourceId]);
$pdo->prepare('INSERT INTO project_sources(project_id,source_id,added_by_user_id) VALUES(?,?,?)')->execute([$projectId,$sourceId,$owner['id']]);$pdo->prepare('INSERT INTO source_watches(source_id,user_id) VALUES(?,?)')->execute([$sourceId,$owner['id']]);
