$teamPublic=$pub('team');$pdo->prepare('INSERT INTO teams(public_id,owner_user_id,name) VALUES(?,?,?)')->execute([$teamPublic,$owner['id'],'Proactive Team']);$teamId=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO team_members(team_id,user_id,role) VALUES(?,?,'owner')")->execute([$teamId,$owner['id']]);
$teamContext=['refs'=>[['type'=>'team','public_id'=>$teamPublic]]];p17(proactive_context_access($pdo,$owner,$teamContext),'current Team member may access proactive Team context');$pdo->prepare('DELETE FROM team_members WHERE team_id=? AND user_id=?')->execute([$teamId,$owner['id']]);p17(!proactive_context_access($pdo,$owner,$teamContext),'revoked Team member loses stored proactive Team context immediately');
$synthetic=['type'=>'recent_change','priority'=>'low','score'=>30,'title'=>'Routine project change','body'=>'Low priority project activity','actions'=>[cognitive_feed_action_link('Open Research','/research-project.php?id='.rawurlencode($projectPublic))]];
$importantWatch=['status'=>'active','watch_type'=>'project','object_public_id'=>$projectPublic,'alert_level'=>'important'];$allWatch=$importantWatch;$allWatch['alert_level']='all';$matched=null;
p17(!proactive_should_alert($synthetic,$owner,['proactive_notification_mode'=>'mentions'],[$importantWatch],$matched),'important-only watch does not escalate low-priority matching state');
$matched=null;p17(proactive_should_alert($synthetic,$owner,['proactive_notification_mode'=>'mentions'],[$allWatch],$matched),'all-activity watch can surface low-priority matching state');

$jobsBefore=(int)$pdo->query('SELECT COUNT(*) FROM ai_jobs')->fetchColumn();$sync=proactive_intelligence_sync($pdo,$owner);$jobsAfter=(int)$pdo->query('SELECT COUNT(*) FROM ai_jobs')->fetchColumn();
p17($jobsBefore===$jobsAfter,'proactive evaluation creates no AI ranking jobs');p17(($sync['evaluated']??0)>0&&($sync['notified']??0)>0,'important cognitive observations create proactive notifications');
$q=$pdo->prepare("SELECT * FROM notifications WHERE user_id=? AND notification_type='research_proactive' ORDER BY id DESC LIMIT 1");$q->execute([$owner['id']]);$notification=$q->fetch();p17((bool)$notification,'proactive notification is stored in the existing notification center');
$ctx=json_decode((string)$notification['context_json'],true)?:[];p17(!empty($ctx['why'])&&!empty($ctx['observation_key']),'proactive notification carries Why this matters and observation provenance');p17(!array_key_exists('actions',$ctx),'proactive notification does not persist stale Agent prompts or action payloads');
$countBefore=(int)$pdo->query("SELECT COUNT(*) FROM notifications WHERE user_id=".(int)$owner['id']." AND notification_type='research_proactive'")->fetchColumn();proactive_intelligence_sync($pdo,$owner);$countAfter=(int)$pdo->query("SELECT COUNT(*) FROM notifications WHERE user_id=".(int)$owner['id']." AND notification_type='research_proactive'")->fetchColumn();p17($countBefore===$countAfter,'repeated evaluation deduplicates unchanged proactive alerts');

$key=(string)$ctx['observation_key'];p17(proactive_alert_snooze($pdo,$owner,$key,24),'alert can be snoozed');$q=$pdo->prepare('SELECT state FROM cognitive_alert_states WHERE user_id=? AND observation_key=?');$q->execute([$owner['id'],$key]);p17($q->fetchColumn()==='snoozed','snooze state persists per user');
$pdo->prepare('UPDATE cognitive_alert_states SET snoozed_until=DATE_SUB(NOW(),INTERVAL 1 MINUTE) WHERE user_id=? AND observation_key=?')->execute([$owner['id'],$key]);$resumed=proactive_intelligence_sync($pdo,$owner);p17(($resumed['notified']??0)>=1,'expired snooze allows the alert to surface again');
p17(proactive_alert_resolve($pdo,$owner,$key),'alert can be resolved');proactive_intelligence_sync($pdo,$owner);$q=$pdo->prepare('SELECT state FROM cognitive_alert_states WHERE user_id=? AND observation_key=?');$q->execute([$owner['id'],$key]);p17($q->fetchColumn()==='resolved','resolved unchanged state stays resolved');

$liveFeed=cognitive_feed_compose($pdo,$owner,null,8,60);$sourceObservation=null;foreach(proactive_feed_items($liveFeed) as $candidate)if(($candidate['type']??'')==='source_change'){$sourceObservation=$candidate;break;}p17($sourceObservation!==null,'current source-change observation is available for Agent handoff');$handoff=proactive_agent_handoff($pdo,$owner,(string)$sourceObservation['key']);p17($handoff!==null&&!empty($handoff['prompt'])&&!empty($handoff['context']),'proactive Ask Agent handoff is rebuilt from current permission-checked observation');
